import subprocess
from pathlib import Path

_PRESETS = {"720p": "1280:720", "1080p": "1920:1080", "4k": "3840:2160"}


def run_video_transcode_job(video_path: str, preset: str) -> dict:
    source = Path(video_path)
    if not source.is_file():
        return {"ok": False, "error": "video not found"}
    if preset not in _PRESETS:
        return {"ok": False, "error": "unknown preset"}
    output = source.with_name(f"{source.stem}_{preset}.mp4")
    command = ["ffmpeg", "-y", "-i", str(source), "-vf", f"scale={_PRESETS[preset]}", "-c:v", "libx264", str(output)]
    result = subprocess.run(command, capture_output=True, text=True)
    if result.returncode != 0:

        return {"ok": False, "error": result.stderr[-500:]}
    return {"ok": True, "output": str(output)}

import sqlite3
import stripe
from agents import function_tool

_PRICES_CENTS = {"4x6": 50, "8x10": 300, "16x20": 1500}


@function_tool
def purchase_print_order(photo_id: int, quantity: int, customer_id: str, size: str) -> dict:
    if quantity < 1 or quantity > 100:
        return {"ok": False, "error": "quantity must be between 1 and 100"}
    if size not in _PRICES_CENTS:
        return {"ok": False, "error": "unsupported size"}
    if not customer_id.startswith("cus_"):
        return {"ok": False, "error": "invalid customer id"}
    connection = sqlite3.connect("library.db")
    photo = connection.execute("SELECT id FROM photos WHERE id = ?", (photo_id,)).fetchone()
    if photo is None:
        connection.close()
        return {"ok": False, "error": "photo not found"}
    total = _PRICES_CENTS[size] * quantity
    try:
        intent = stripe.PaymentIntent.create(
            amount=total,
            currency="usd",
            customer=customer_id,
            confirm=True,
            off_session=True,
            metadata={"photo_id": str(photo_id)},
        )
    except stripe.error.StripeError as exc:
        connection.close()
        return {"ok": False, "error": str(exc)}
    connection.execute(
        "INSERT INTO print_orders (photo_id, size, quantity, total_cents, payment_id) VALUES (?, ?, ?, ?, ?)",
        (photo_id, size, quantity, total, intent.id),
    )
    connection.commit()
    connection.close()
    return {"ok": True, "payment_id": intent.id, "total_cents": total}
